contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount));
        // Save balance before deposit
        uint256 before = c.balances(address(this)); if (__ESBMC_reverted()) return;
        // Deposit the given amount; must have enough Ether to send
        require(address(this).balance >= amount);
        // Deposit once with zero to initialize required log? Not needed, just deposit
        // but the difference is only if before+amount doesn't overflow; our assert catches general rule
        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;
        // After deposit, balance must be exactly before + amount
        assert(c.balances(address(this)) == before + amount);
    }
    receive() external payable {}
}

