pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK as DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        uint256 before;
        try c.balances(address(this)) returns (uint256 __r) { before = __r; } catch { return; }
        vm.assume(address(this).balance >= amount);
        try c.Deposit{value: amount}() {} catch { return; }
        assertTrue(c.balances(address(this)) == before + amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}

